  internal const string Argument="-javaagent:OrangeLauncherRuntime/environment/OrangeEnvironment.jar";
  const string AgentFile="game/OrangeLauncherRuntime/environment/OrangeEnvironment.jar",PropertiesFile="game/OrangeLauncherRuntime/environment/environment.properties";
  const int ConfigLimit=2097152,JarLimit=33554432;
  static readonly UTF8Encoding Utf8=new UTF8Encoding(false,true);
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=4194304,RecursionLimit=32};}
  static string Full(string path){if(!Path.IsPathRooted(path??""))throw new IOException("快照运行路径必须为绝对路径。");string full=VersionLibrary.Full(path);LauncherMaintenance.NoReparse(full);return full;}
  static bool Same(string a,string b){return VersionLibrary.Same(a,b);}
  static bool Within(string a,string b){return VersionLibrary.Within(a,b);}
  static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  static string FileHash(string file){Full(file);using(var sha=SHA256.Create())using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read))return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant();}
  static byte[] Read(string path,int maximum,bool required=true){Full(path);if(Directory.Exists(path))throw new IOException("快照文件路径被目录占用。");if(!File.Exists(path)){if(required)throw new IOException("快照运行文件缺失。");return null;}using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){if(input.Length>maximum)throw new IOException("快照运行文件超过读取上限。");byte[] bytes=new byte[(int)input.Length];int offset=0,count;while(offset<bytes.Length&&(count=input.Read(bytes,offset,bytes.Length-offset))>0)offset+=count;if(offset!=bytes.Length)throw new IOException("快照运行文件在读取期间改变。");return bytes;}}
  static string Child(SaveEnvironmentRecord row,string relative){if(string.IsNullOrWhiteSpace(relative)||relative.Contains('\\')||relative.Split('/').Any(part=>part==""||part=="."||part==".."))throw new IOException("快照运行文件名无效。");string path=Full(Path.Combine(row.RootPath,relative.Replace('/',Path.DirectorySeparatorChar)));if(!Within(path,row.RootPath)||Same(path,row.RootPath))throw new IOException("快照运行文件越界。");return path;}
  static string[] Strings(object value){if(value==null)return new string[0];if(value is string||!(value is IEnumerable)||value is IDictionary)throw new IOException("快照启动数组无效。");var values=((IEnumerable)value).Cast<object>().ToArray();if(values.Any(item=>!(item is string)))throw new IOException("快照启动数组必须为文本。");return values.Cast<string>().ToArray();}
  static string[] Args(Dictionary<string,object> node){object value;return node.TryGetValue("vmArgs",out value)?Strings(value):new string[0];}
  static IEnumerable<Dictionary<string,object>> Nodes(Dictionary<string,object> node){yield return node;foreach(var child in node.Values.OfType<Dictionary<string,object>>())foreach(var nested in Nodes(child))yield return nested;}
  static Dictionary<string,object> Config(byte[] bytes){try{var config=Json().Deserialize<Dictionary<string,object>>(Utf8.GetString(bytes).TrimStart('\uFEFF'));if(config==null||!config.ContainsKey("vmArgs"))throw new IOException("缺少 vmArgs。");foreach(var node in Nodes(config))if(node.ContainsKey("vmArgs"))Args(node);return config;}catch(Exception error){throw new IOException("无法识别快照启动配置。",error);}}
  static void EnvironmentArguments(){foreach(string name in new[]{"JAVA_TOOL_OPTIONS","_JAVA_OPTIONS","JDK_JAVA_OPTIONS"})if(!string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(name)))throw new IOException("Java 环境变量含额外启动覆盖，未继续使用快照。");}
  static SaveEnvironmentRecord Owned(Engine e){if(e==null||e.FrozenEnvironment==null)throw new IOException("当前游戏未登记为存档快照。");var row=SaveEnvironments.FindOwned(e.Data,e.Game,e.User);if(row==null||row.Id!=e.FrozenEnvironment.Id)throw new IOException("存档快照登记身份已变化。");return row;}
  static byte[] Pinned(SaveEnvironmentRecord row,string relative,int maximum){string path=Child(row,relative);var matches=(row.Files??new SaveEnvironmentFile[0]).Where(file=>!file.Directory&&file.Path.Equals(relative,StringComparison.OrdinalIgnoreCase)).ToArray();if(matches.Length!=1)throw new IOException("文件不在登记的快照运行清单中。");var expected=matches[0];byte[] bytes=Read(path,maximum);if(bytes.LongLength!=expected.Bytes||Hash(bytes)!=expected.Hash)throw new IOException("快照运行文件校验失败，请重新核对快照。");return bytes;}
  internal static byte[] PinnedFile(Engine e,string relative,int maximum){if(maximum<1||maximum>67108864)throw new IOException("快照读取上限无效。");return Pinned(Owned(e),relative,maximum);}
  internal static bool IsOwnedArgument(Engine e,string argument){if(argument==GameStartupComponent.Argument)return GameStartupComponent.IsOwnedArgument(e,argument);if(argument!=Argument||e==null||e.FrozenEnvironment==null)return false;try{Pinned(Owned(e),AgentFile,JarLimit);return true;}catch{return false;}}
  static byte[] Properties(SaveEnvironmentRecord row){Func<string,string> encode=path=>Convert.ToBase64String(Utf8.GetBytes(Full(path)));string text="version=OZLENV1\nid="+row.Id+"\ngame="+encode(row.GamePath)+"\nuser="+encode(row.UserPath)+"\nhome="+encode(row.RuntimeHome)+"\nmods="+encode(Path.Combine(row.RootPath,"runtime","mods"))+"\nroots="+string.Join(",",row.ModRoots.Select(mapping=>encode(mapping.CopiedRoot)))+"\nbridge="+encode(Path.Combine(row.UserPath,"mods","OrangeLauncherSession"))+"\n";return Encoding.ASCII.GetBytes(text);}
  // Captured source paths are mapping keys only. They must never consult a live
  // Workshop directory while validating an already registered snapshot.
  static string CapturedPath(string path){if(!Path.IsPathRooted(path??""))throw new IOException("捕获的 Java 来源路径必须为绝对路径。");return VersionLibrary.Full(path);}
  static string Remap(SaveEnvironmentRecord row,string path,string modId=null){path=CapturedPath(path);var matches=row.ModRoots.Where(candidate=>Within(path,candidate.SourceRoot)&&(modId==null||candidate.ModIds.Any(id=>id.TrimStart('\\')==modId.TrimStart('\\')))).OrderByDescending(candidate=>candidate.SourceRoot.Length).ToArray();if(matches.Length==0)throw new IOException("Buddy 预加载指向未捕获的模组来源。");var mapping=matches[0];string suffix=path.Substring(CapturedPath(mapping.SourceRoot).Length).TrimStart('\\','/');string copied=Full(Path.Combine(mapping.CopiedRoot,suffix));if(!Within(copied,mapping.CopiedRoot)||Same(copied,mapping.CopiedRoot))throw new IOException("Buddy 预加载映射越界。");string relative=copied.Substring(Full(mapping.CopiedRoot).Length+1).Replace('\\','/');var expected=mapping.SourceFiles.SingleOrDefault(file=>!file.Directory&&file.Path==relative);if(expected==null||!File.Exists(copied)||new FileInfo(copied).Length!=expected.Bytes||FileHash(copied)!=expected.Hash)throw new IOException("复制的 Buddy 预加载文件与捕获内容不一致。");return copied;}
  static Dictionary<string,object> BuddyConfig(SaveEnvironmentRecord row){var config=row.BuddyConfigBytes==null?new Dictionary<string,object>():ConfigObject(row.BuddyConfigBytes);object value;var result=new Dictionary<string,object>(StringComparer.Ordinal);if(config.TryGetValue("preload_mods",out value)){var preloads=value as Dictionary<string,object>;if(preloads==null)throw new IOException("Buddy 预加载配置无效。");foreach(var pair in preloads){var item=pair.Value as Dictionary<string,object>;object info,jar;if(item==null||!item.TryGetValue("infPath",out info)||!(info is string)||!item.TryGetValue("jarPath",out jar)||!(jar is string))throw new IOException("Buddy 预加载来源不完整。");if(!(row.PreloadModIds??new string[0]).Contains(pair.Key.TrimStart('\\'),StringComparer.Ordinal))throw new IOException("Buddy 预加载不在捕获清单中。");var mapped=new Dictionary<string,object>(item);mapped["infPath"]=Remap(row,(string)info,pair.Key);mapped["jarPath"]=Remap(row,(string)jar,pair.Key);result.Add(pair.Key,mapped);}}
   config["preload_mods"]=result;config["trusted_authors"]=new object[0];config["auto_fix_mod_order"]=false;return config;
  }
  static Dictionary<string,object> ConfigObject(byte[] bytes){var value=Json().Deserialize<Dictionary<string,object>>(Utf8.GetString(bytes).TrimStart('\uFEFF'));if(value==null)throw new IOException("Buddy 配置格式无效。");return value;}
  static byte[] Approvals(SaveEnvironmentRecord row){var result=new Dictionary<string,object>{{"formatVersion",2},{"mods",new object[0]}};if(row.ApprovalBytes==null)return Utf8.GetBytes(Json().Serialize(result));try{var source=ConfigObject(row.ApprovalBytes);object version,raw;if(!source.TryGetValue("formatVersion",out version)||!(version is int)||(int)version!=2||!source.TryGetValue("mods",out raw)||!(raw is IList))return Utf8.GetBytes(Json().Serialize(result));var allowed=new HashSet<string>(StringComparer.Ordinal);foreach(var mapping in row.ModRoots)foreach(var file in mapping.SourceFiles.Where(file=>!file.Directory&&file.Path.EndsWith(".jar",StringComparison.OrdinalIgnoreCase))){string path=Full(Path.Combine(mapping.CopiedRoot,file.Path.Replace('/',Path.DirectorySeparatorChar)));if(FileHash(path)==file.Hash)allowed.Add(file.Hash);}
    var rows=new List<Dictionary<string,object>>();var decisions=new Dictionary<string,bool>(StringComparer.Ordinal);foreach(var item in (IList)raw){var entry=item as Dictionary<string,object>;object hash,decision;if(entry==null||!entry.TryGetValue("jar_hash",out hash)||!(hash is string)||!Regex.IsMatch((string)hash,@"\A[a-f0-9]{64}\z")||!entry.TryGetValue("decision",out decision)||!(decision is bool))throw new IOException("授权记录格式不明确。");bool previous;if(decisions.TryGetValue((string)hash,out previous)&&previous!=(bool)decision)throw new IOException("授权记录决定冲突。");decisions[(string)hash]=(bool)decision;if(!allowed.Contains((string)hash))continue;var copied=new Dictionary<string,object>{{"jar_hash",hash},{"decision",decision}};object id;if(entry.TryGetValue("id",out id)&&id is string&&SaveProfiles.Id((string)id))copied["id"]=id;rows.Add(copied);}result["mods"]=rows;
   }catch{result["mods"]=new object[0];}return Utf8.GetBytes(Json().Serialize(result));
  }
  static string GamePath(string value,SaveEnvironmentRecord row){if(Path.IsPathRooted(value)){string source=Full(value);if(!Within(source,row.SourceGame))throw new IOException("启动路径指向游戏快照之外，无法冻结。");return Full(Path.Combine(row.GamePath,source.Substring(Full(row.SourceGame).Length).TrimStart('\\','/')));}string target=Full(Path.Combine(row.GamePath,value));if(!Within(target,row.GamePath))throw new IOException("启动相对路径越界。");return value;}
  static bool Buddy(string argument,SaveEnvironmentRecord row,out string normalized){normalized=null;string tail=null;if(argument.StartsWith("-agentlib:zbNative",StringComparison.Ordinal)){tail=argument.Substring(18);normalized="-agentlib:zbNative";}else if(argument.StartsWith("-javaagent:",StringComparison.Ordinal)){string value=argument.Substring(11);int at=value.IndexOf('=');string file=at<0?value:value.Substring(0,at);if(!Path.GetFileName(file).Equals("ZombieBuddy.jar",StringComparison.OrdinalIgnoreCase))return false;string resolved=Path.IsPathRooted(file)?Full(file):Full(Path.Combine(row.SourceGame,file));if(!Same(resolved,Path.Combine(row.SourceGame,"ZombieBuddy.jar"))&&!Same(resolved,Path.Combine(row.GamePath,"ZombieBuddy.jar")))throw new IOException("Buddy 代理位于捕获游戏之外。");tail=at<0?"":value.Substring(at);normalized="-javaagent:ZombieBuddy.jar";}else return false;
   if(tail!=""){if(!tail.StartsWith("=config_dir=",StringComparison.Ordinal)||tail.Substring(12).Contains(','))throw new IOException("Buddy 自定义启动选项无法冻结。");Full(tail.Substring(12));}return true;
  }
  static void Unexpected(string arg){if(arg.StartsWith("-agentpath:",StringComparison.OrdinalIgnoreCase)||arg.StartsWith("-agentlib:",StringComparison.OrdinalIgnoreCase)||arg.StartsWith("-javaagent:",StringComparison.OrdinalIgnoreCase)||arg.StartsWith("-Duser.dir=",StringComparison.OrdinalIgnoreCase)||arg.StartsWith("-Xbootclasspath",StringComparison.OrdinalIgnoreCase)||arg.StartsWith("-XX:SharedArchiveFile",StringComparison.OrdinalIgnoreCase)||arg.StartsWith("-Dozl.environment",StringComparison.OrdinalIgnoreCase)||arg.StartsWith("-D",StringComparison.Ordinal)&&arg.IndexOf("config_dir",StringComparison.OrdinalIgnoreCase)>=0)throw new IOException("存在无法归属的 Java 代理或目录覆盖，未使用快照。");}
  static Dictionary<string,object> LaunchConfig(Engine source,SaveEnvironmentRecord row,byte[] properties,out bool startup){var config=Config(Read(Path.Combine(row.GamePath,"ProjectZomboid64.json"),ConfigLimit));startup=false;bool validStartup=GameStartupComponent.IsOwnedArgument(source,GameStartupComponent.Argument)||GameStartupComponent.CanPrepareOwnedArgument(source,GameStartupComponent.Argument);foreach(var node in Nodes(config)){if(node.ContainsKey("classpath"))node["classpath"]=Strings(node["classpath"]).Select(value=>GamePath(value,row)).ToArray();if(!node.ContainsKey("vmArgs"))continue;var args=new List<string>();foreach(string arg in Args(node)){string normalized;if(arg.StartsWith("-Duser.home=",StringComparison.Ordinal)){Full(arg.Substring(12));continue;}if(arg==GameStartupComponent.Argument){if(!validStartup)throw new IOException("复制的可选加载页代理没有有效归属。");startup=true;continue;}if(Buddy(arg,row,out normalized)){args.Add(normalized);continue;}Unexpected(arg);if(arg.StartsWith("-Djava.library.path=",StringComparison.Ordinal)){args.Add("-Djava.library.path="+string.Join(";",arg.Substring(20).Split(';').Select(value=>GamePath(value,row))));continue;}if(arg.StartsWith("-Djava.home=",StringComparison.Ordinal)){args.Add("-Djava.home="+GamePath(arg.Substring(12),row));continue;}args.Add(arg);}node["vmArgs"]=args.ToArray();}
   var common=Args(config).ToList();common.Insert(0,Argument);common.Add("-Dozl.environment="+Child(row,PropertiesFile));common.Add("-Dozl.environment.sha256="+Hash(properties));common.Add("-Duser.home="+row.RuntimeHome);if(startup)common.Add(GameStartupComponent.Argument);config["vmArgs"]=common.ToArray();return config;
  }
  static void NewDestination(Engine source,SaveEnvironmentRecord row){if(source==null||row==null||source.FrozenEnvironment!=null||!Regex.IsMatch(row.Id??"",@"\A[a-f0-9]{32}\z")||!Same(source.Game,row.SourceGame)||!Same(source.User,row.UserPath)||!Same(row.GamePath,Path.Combine(row.RootPath,"game"))||!Same(row.RuntimeHome,Path.Combine(row.RootPath,"runtime","home"))||Within(row.RootPath,source.Game)||Within(source.Game,row.RootPath)||Within(row.RootPath,source.User)||Within(source.User,row.RootPath)||Within(row.RootPath,source.Data)||Within(source.Data,row.RootPath))throw new IOException("运行环境准备仅接受新建且独立的自有快照。");Full(row.RootPath);Full(row.GamePath);Full(row.RuntimeHome);if(!Directory.Exists(row.GamePath)||!Read(Path.Combine(row.RootPath,".owner"),64).SequenceEqual(Utf8.GetBytes(row.Id))||string.IsNullOrEmpty(row.RootIdentity)||Identity(row.RootPath)!=row.RootIdentity||File.Exists(Path.Combine(row.RootPath,SaveEnvironments.ManifestName))||File.Exists(Child(row,PropertiesFile))||row.ModRoots==null||row.DefaultModIds==null||row.ModIds==null)throw new IOException("快照目录缺少新建所有权或已经发布。");foreach(var mapping in row.ModRoots){if(mapping==null||mapping.SourceFiles==null||mapping.ModIds==null||!Within(mapping.CopiedRoot,Path.Combine(row.RootPath,"mods"))||Same(mapping.CopiedRoot,Path.Combine(row.RootPath,"mods"))||!Within(mapping.Layout,mapping.CopiedRoot)||mapping.CommonRoot!=null&&!Within(mapping.CommonRoot,mapping.CopiedRoot))throw new IOException("新快照模组路径映射无效。");Full(mapping.CopiedRoot);}}
  internal static void Prepare(Engine source,SaveEnvironmentRecord row){EnvironmentArguments();NewDestination(source,row);byte[] properties=Properties(row);bool startup;var config=LaunchConfig(source,row,properties,out startup);var buddy=BuddyConfig(row);byte[] approvals=Approvals(row);var writes=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase){{Child(row,AgentFile),BundledAssets.ReadOwnAsset("OrangeEnvironment.jar")},{Child(row,PropertiesFile),properties},{Path.Combine(row.RootPath,"runtime","mods","default.txt"),SaveProfiles.ReplaceDefaultMods(row.DefaultBytes,row.DefaultModIds)},{Path.Combine(row.RootPath,"runtime","mods","loaded.txt"),Utf8.GetBytes(string.Join("\n",row.DefaultModIds)+"\n")},{Path.Combine(row.RuntimeHome,".zombie_buddy","config.json"),Utf8.GetBytes(Json().Serialize(buddy))},{Path.Combine(row.RuntimeHome,".zombie_buddy","mod_approvals.json"),approvals},{Path.Combine(row.GamePath,"ProjectZomboid64.json"),Utf8.GetBytes(Json().Serialize(config))}};
   if(startup)writes.Add(Child(row,"game/OrangeLauncherRuntime/startup/OrangeStartup.jar"),BundledAssets.ReadOwnAsset("OrangeStartup.jar"));foreach(var pair in writes){Full(pair.Key);if(!Within(pair.Key,row.RootPath)||pair.Value==null||pair.Value.Length==0)throw new IOException("快照运行准备输出无效。");}
   bool copiedStartup=GameStartupComponent.IsOwnedArgument(source,GameStartupComponent.Argument)||GameStartupComponent.CanPrepareOwnedArgument(source,GameStartupComponent.Argument);NewDestination(source,row);string agent=Child(row,AgentFile);Directory.CreateDirectory(Path.GetDirectoryName(agent));File.WriteAllBytes(agent,writes[agent]);if(!source.TestMode)Probe(row,agent);foreach(var pair in writes.Where(pair=>!Same(pair.Key,agent))){Directory.CreateDirectory(Path.GetDirectoryName(pair.Key));File.WriteAllBytes(pair.Key,pair.Value);}if(copiedStartup)foreach(string name in new[]{"session.properties","issues.txt","ownership.json"}){string path=Child(row,"game/OrangeLauncherRuntime/startup/"+name);if(File.Exists(path))File.Delete(path);}
  }
  static string Quote(string value){var result=new StringBuilder("\"");int slashes=0;foreach(char c in value){if(c=='\\'){slashes++;continue;}if(c=='"'){result.Append('\\',slashes*2+1);result.Append(c);}else{result.Append('\\',slashes);result.Append(c);}slashes=0;}return result.Append('\\',slashes*2).Append('"').ToString();}
  static string BoundedOutput(StreamReader reader){var result=new StringBuilder();var buffer=new char[1024];int count;while((count=reader.Read(buffer,0,buffer.Length))>0)if(result.Length<8192)result.Append(buffer,0,Math.Min(count,8192-result.Length));return result.ToString();}
  static void StopProbe(Process process){try{process.Kill();process.WaitForExit(2000);}catch{}}
  static void Probe(SaveEnvironmentRecord row,string agent){Probe(row.GamePath,row.RuntimeHome,agent,CancellationToken.None);}
  static void Probe(string game,string home,string agent,CancellationToken cancellation){try{cancellation.ThrowIfCancellationRequested();game=Full(game);home=Full(home);agent=Full(agent);string java=Full(Path.Combine(game,"jre64","bin","java.exe"));if(!File.Exists(java))throw new IOException("Snapshot JRE is missing.");var start=new ProcessStartInfo(java,string.Join(" ",new[]{"-Djava.awt.headless=true","-Duser.home="+home,"-cp",agent,"ozl.environment.EnvironmentProbe",game}.Select(Quote))){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=game,RedirectStandardOutput=true,RedirectStandardError=true};using(var process=Process.Start(start)){if(process==null)throw new IOException("Snapshot API probe did not start.");var output=Task.Run(()=>BoundedOutput(process.StandardOutput));var error=Task.Run(()=>BoundedOutput(process.StandardError));var watch=Stopwatch.StartNew();while(!process.WaitForExit(100)){if(cancellation.IsCancellationRequested){StopProbe(process);cancellation.ThrowIfCancellationRequested();}if(watch.ElapsedMilliseconds>=15000){StopProbe(process);throw new IOException("Snapshot API probe timed out.");}}if(!Task.WaitAll(new Task[]{output,error},2000))throw new IOException("Snapshot API probe output did not close.");cancellation.ThrowIfCancellationRequested();if(process.ExitCode!=0)throw new IOException("Snapshot API probe exited "+process.ExitCode+": "+error.Result+" "+output.Result);}}
   catch(OperationCanceledException){throw;}catch(Exception error){throw new IOException("这个游戏版本暂不支持快照，请保留当前环境。",error);}
  }
  internal static void CheckSource(Engine source,CancellationToken cancellation){if(source==null)throw new ArgumentNullException("source");cancellation.ThrowIfCancellationRequested();if(source.TestMode)return;EnvironmentArguments();byte[] payload=BundledAssets.ReadOwnAsset("OrangeEnvironment.jar");if(payload==null||payload.Length==0||payload.Length>JarLimit)throw new IOException("内置快照组件缺失或大小异常。");string parent=Full(Path.GetTempPath()),id=Guid.NewGuid().ToString("N"),root=Full(Path.Combine(parent,"ozl-env-probe-"+id)),identity=null;if(!Within(root,parent)||Same(root,parent))throw new IOException("临时快照检测目录越界。");if(!CreateTemporaryDirectory(root,IntPtr.Zero))throw new Win32Exception(Marshal.GetLastWin32Error(),"无法建立独立快照检测目录。");try{identity=Identity(root);using(var marker=new FileStream(Path.Combine(root,".owner"),FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] bytes=Utf8.GetBytes(id);marker.Write(bytes,0,bytes.Length);}string home=Full(Path.Combine(root,"home")),agent=Full(Path.Combine(root,"OrangeEnvironment.jar"));Directory.CreateDirectory(home);using(var file=new FileStream(agent,FileMode.CreateNew,FileAccess.Write,FileShare.None)){file.Write(payload,0,payload.Length);}cancellation.ThrowIfCancellationRequested();Probe(source.Game,home,agent,cancellation);cancellation.ThrowIfCancellationRequested();}finally{if(identity!=null){if(!Within(Full(root),Full(parent))||Same(root,parent)||Path.GetFileName(root)!="ozl-env-probe-"+id||Identity(root)!=identity||!Read(Path.Combine(root,".owner"),64).SequenceEqual(Utf8.GetBytes(id)))throw new IOException("快照检测临时目录归属已变化，未自动清理。");RemoveProbeTree(root,root);}}}
  static void RemoveProbeTree(string owner,string directory){directory=Full(directory);if(!Same(directory,owner)&&!Within(directory,owner))throw new IOException("临时快照检测清理路径越界。");foreach(string child in Directory.EnumerateFileSystemEntries(directory)){string path=Full(child);if(!Within(path,owner)||Same(path,owner))throw new IOException("临时快照检测内容越界。");if(Directory.Exists(path))RemoveProbeTree(owner,path);else File.Delete(path);}Full(directory);Directory.Delete(directory,false);}
  static void ValidateBuddy(SaveEnvironmentRecord row){string path=Path.Combine(row.RuntimeHome,".zombie_buddy","config.json");var config=ConfigObject(Read(path,ConfigLimit));object value;if(!config.TryGetValue("preload_mods",out value)||!(value is Dictionary<string,object>))throw new IOException("快照 Buddy 预加载配置无效。");var actual=(Dictionary<string,object>)value;var captured=(Dictionary<string,object>)BuddyConfig(row)["preload_mods"];if(actual.Count!=captured.Count||actual.Keys.Except(captured.Keys,StringComparer.Ordinal).Any())throw new IOException("快照 Buddy 预加载通道已偏离捕获清单。");foreach(var pair in actual){var item=pair.Value as Dictionary<string,object>;var original=(Dictionary<string,object>)captured[pair.Key];object info,jar;if(item==null||!item.TryGetValue("infPath",out info)||!(info is string)||!item.TryGetValue("jarPath",out jar)||!(jar is string)||!Same((string)info,(string)original["infPath"])||!Same((string)jar,(string)original["jarPath"]))throw new IOException("快照 Buddy 预加载路径已偏离固定映射。");foreach(string file in new[]{(string)info,(string)jar}){string full=Full(file);if(!row.ModRoots.Any(mapping=>Within(full,mapping.CopiedRoot)&&mapping.ModIds.Any(id=>id.TrimStart('\\')==pair.Key.TrimStart('\\'))))throw new IOException("快照 Buddy 预加载指向未捕获的来源。");string relative=full.Substring(Full(row.RootPath).Length+1).Replace('\\','/');var expected=row.Files.SingleOrDefault(entry=>!entry.Directory&&entry.Path.Equals(relative,StringComparison.OrdinalIgnoreCase));if(expected==null||!File.Exists(full)||new FileInfo(full).Length!=expected.Bytes||FileHash(full)!=expected.Hash)throw new IOException("快照 Buddy 预加载文件已偏离捕获内容。");}}}
