  static string ComponentSource(SaveEnvironmentRecord row,string id){var roots=row.ModRoots.Where(mapping=>mapping.ModIds.Any(value=>value.TrimStart('\\')==id)).ToArray();return roots.Length==1?Path.GetDirectoryName(Path.GetDirectoryName(roots[0].CopiedRoot)):null;}
